370		// pageSize=100 is allowed; page=1 default applies.
371		rec := getSBOMs(t, router, "/sboms?artifact=a&pageSize=100")
372		if rec.Code != http.StatusOK {
373			t.Fatalf("pageSize 100: %d %s", rec.Code, rec.Body.String())
374		}
375	}
376	
377	func TestPersistsAcrossReopen(t *testing.T) {
378		dir := t.TempDir()
379		path := filepath.Join(dir, "service.db")
380	
381		st, err := store.Open(path)
382		if err != nil {
383			t.Fatalf("open: %v", err)
384		}
385		router1 := NewRouter(st)
386		rec := postSBOM(t, router1, `{"artifact":"app","version":"1","components":[{"coordinate":"c","license":"L","dependencies":[]}]}`)
387		var first model.SBOM
388		decodeBody(t, rec, &first)
389		if err := st.Close(); err != nil {
390			t.Fatalf("close: %v", err)
391		}
392	
393		st2, err := store.Open(path)
394		if err != nil {
395			t.Fatalf("reopen: %v", err)
396		}
397		defer st2.Close()
398		router2 := NewRouter(st2)
399	
400		// Same manifest after reopen: same id, 201.
401		rec = postSBOM(t, router2, `{"artifact":"app","version":"1","components":[{"coordinate":"c","license":"L","dependencies":[]}]}`)
402		if rec.Code != http.StatusCreated {
403			t.Fatalf("re-register after reopen: %d %s", rec.Code, rec.Body.String())
404		}
405		var again model.SBOM
406		decodeBody(t, rec, &again)
407		if again.ID != first.ID {
408			t.Fatalf("id after reopen = %d, want %d", again.ID, first.ID)
409		}
410	
411		// Changed content after reopen still conflicts.
412		expectError(t, postSBOM(t, router2,
413			`{"artifact":"app","version":"1","components":[{"coordinate":"c","license":"X","dependencies":[]}]}`),
414			http.StatusConflict, "SbomConflictError")
415	
416		// Query sees the persisted record.
417		rec = getSBOMs(t, router2, "/sboms?artifact=app")
418		var page listResponse
419		decodeBody(t, rec, &page)
420		if page.Total != 1 || page.Items[0].ID != first.ID {
421			t.Fatalf("list after reopen = %+v", page)
422		}
423	}
424	
425	func TestConcurrentIdenticalRegistersShareOneRecord(t *testing.T) {
426		router, _ := newTestRouter(t)
427		body := `{"artifact":"race","version":"1","components":[
428			{"coordinate":"a","license":"L","dependencies":["b"]},
429			{"coordinate":"b","license":"L","dependencies":[]}
430		]}`
431		const n = 8
432		var wg sync.WaitGroup
433		ids := make(chan int64, n)
434		statuses := make(chan int, n)
435		for i := 0; i < n; i++ {
436			wg.Add(1)
437			go func() {
438				defer wg.Done()
439				rec := postSBOM(t, router, body)
440				statuses <- rec.Code
441				if rec.Code == http.StatusCreated {
442					var got model.SBOM
443					json.Unmarshal(rec.Body.Bytes(), &got)
444					ids <- got.ID
445				}
446			}()
447		}
448		wg.Wait()
449		close(ids)
450		close(statuses)
451	
452		first := int64(-1)
453		for status := range statuses {
454			if status != http.StatusCreated {
455				t.Fatalf("concurrent register status = %d, want 201", status)
456			}
457		}
458		count := 0
459		for id := range ids {
460			if first == -1 {
461				first = id
462			} else if id != first {
463				t.Fatalf("concurrent registers produced ids %d and %d", first, id)
464			}
465			count++
466		}
467		if count != n {
468			t.Fatalf("created responses = %d, want %d", count, n)
469		}
470	}
