488	func assertSBOMEqual(t *testing.T, got, want *model.SBOM) {
489		t.Helper()
490		if got.Artifact != want.Artifact || got.Version != want.Version {
491			t.Fatalf("artifact/version = %q/%q, want %q/%q", got.Artifact, got.Version, want.Artifact, want.Version)
492		}
493		if len(got.Components) != len(want.Components) {
494			t.Fatalf("components len = %d, want %d", len(got.Components), len(want.Components))
495		}
496		for i := range want.Components {
497			g, w := got.Components[i], want.Components[i]
498			if g.Coordinate != w.Coordinate || g.License != w.License {
499				t.Fatalf("component %d = %+v, want %+v", i, g, w)
500			}
501			if len(g.Dependencies) != len(w.Dependencies) {
502				t.Fatalf("deps of %s = %v, want %v", g.Coordinate, g.Dependencies, w.Dependencies)
503			}
504			for j := range w.Dependencies {
505				if g.Dependencies[j] != w.Dependencies[j] {
506					t.Fatalf("deps of %s = %v, want %v", g.Coordinate, g.Dependencies, w.Dependencies)
507				}
508			}
509		}
510	}
